"""Transaction-local program dice receipts; never generated by a language model."""
from __future__ import annotations

from contextlib import contextmanager
from contextvars import ContextVar
from dataclasses import dataclass, field
import hashlib
import json
import re
import time
import uuid

from cockp.core.contracts import Output, Visibility


_active = ContextVar("cockp_dice_receipts", default=None)
HIDDEN_NOTICE = "【暗骰】\n已完成暗骰。"
_SOURCES = {"builtin": "内置骰子", "external": "外部骰娘"}


@dataclass
class ReceiptCollection:
    campaign_id: str | None = None
    group_id: str | None = None
    records: dict = field(default_factory=dict)


@contextmanager
def collect_receipts(*, campaign_id=None, group_id=None):
    collection = ReceiptCollection(campaign_id, group_id)
    token = _active.set(collection)
    try:
        yield collection
    finally:
        _active.reset(token)


def record_roll(roll, **context):
    """Record a returned program result, including persisted/cache reuse."""
    collection = _active.get()
    if collection is None:
        return
    if ((collection.campaign_id is not None and roll.campaign_id != collection.campaign_id)
            or (collection.group_id is not None and roll.group_id != collection.group_id)):
        raise ValueError("dice_receipt_scope_mismatch")
    # Constant expressions used by rule arithmetic do not consume dice.
    if not any(term.count for term in roll.terms) and not roll.candidates:
        return
    if roll.source not in _SOURCES:
        raise ValueError("unsupported_dice_receipt_source")
    data = roll.model_dump(mode="json")
    previous = collection.records.get(roll.request_id)
    if previous is not None:
        if previous["data"] != data:
            raise ValueError("conflicting_dice_receipt_result")
        if any(key in previous["context"] and previous["context"][key] != value for key, value in context.items()):
            raise ValueError("conflicting_dice_receipt_context")
        previous["context"].update(context)
    else:
        collection.records[roll.request_id] = {
            "data": data, "roll": roll.model_copy(deep=True), "context": dict(context)}


def deferred_roll_text(roll):
    """Legacy rule prose keeps only consequences; receipts are finalized once."""
    if _active.get() is not None:
        record_roll(roll)
        return ""
    return format_receipt(roll)


def _text(value, limit=500):
    return re.sub(r"\s+", " ", str(value)).strip()[:limit]


def format_receipt(roll, context=None):
    from cockp.dice.dice import format_expression_roll, normalize_expression
    context = context or {}
    usage = context.get("usage", "rule")
    label = {"reference": "参考", "formal": "正式", "rule": "规则"}[usage]
    if roll.visibility != "public":
        label = "暗骰"
    lines = [f"【掷骰 · {label}】"]
    if context.get("repeat_count", 1) > 1:
        lines.append(f"次数：{context['repeat_index']}/{context['repeat_count']}")
    purpose = " · ".join(_text(context[k], 100) for k in ("character", "skill") if context.get(k))
    if context.get("character") and not context.get("skill"):
        purpose += " · " + (_text(roll.reason, 100) or "投骰")
    if purpose:
        lines.append("用途：" + purpose)
    lines.append("来源：" + _SOURCES[roll.source])
    expression = normalize_expression(roll.expression).replace("*", "×")
    lines.append("骰式：" + expression)
    if roll.candidates:
        modifier = roll.bonus_dice - roll.penalty_dice
        label = "奖励" if modifier > 0 else "惩罚" if modifier < 0 else "抵消"
        lines[-1] += f"（{label}骰）"
        lines.append(f"结果：个位 {roll.units}；十位 {roll.tens}；候选 {roll.candidates} → {roll.total}")
    else:
        lines.append("结果：" + format_expression_roll(roll))
    if "target" in context:
        from cockp.rules.rules import threshold
        difficulty = context["difficulty"]
        name = {"regular": "常规", "hard": "困难", "extreme": "极难"}.get(difficulty, difficulty)
        lines.append(f"目标：{context['target']}；{name}阈值：{threshold(context['target'], difficulty)}")
        lines.append("判定：" + _text(context["outcome"], 100))
    if context.get("action_id"):
        lines.append("行动：" + _text(context["action_id"], 128))
    lines.append("编号：" + hashlib.sha256(roll.request_id.encode()).hexdigest()[:12])
    if not purpose:
        # Result and reference label stay visible in bounded history
        # even when the supplied reason uses its full 500-character allowance.
        lines.append("用途：" + (_text(roll.reason) or "投骰"))
    return "\n".join(lines)


def finalize_receipts(collection, state, actor):
    """Return stable receipt keys and visibility-checked output objects.

    These trusted outputs bypass ordinary prose's public-origin promotion.
    A private invocation never gains a public notice or public detail.
    """
    from cockp.runtime.reply_origin import reply_origin
    origin = reply_origin.get()
    if origin and origin.private and origin.user_id != actor.user_id:
        raise ValueError("dice_receipt_private_origin_mismatch")
    outputs, hidden = [], []
    for ident, item in collection.records.items():
        roll, context = item["roll"], item["context"]
        if roll.character_id in state.get("characters", {}):
            context.setdefault("character", state["characters"][roll.character_id].get("name", ""))
        if roll.visibility == "public":
            visibility = (Visibility(scope="private", recipients=[origin.user_id])
                          if origin and origin.private else Visibility())
        elif roll.visibility == "private":
            if origin and origin.private and origin.user_id != roll.actor_id:
                raise ValueError("dice_receipt_private_actor_mismatch")
            visibility = Visibility(scope="private", recipients=[roll.actor_id])
            hidden.append(ident)
        else:
            visibility = Visibility(scope="kp")
            hidden.append(ident)
        outputs.append(("roll:" + ident, Output(text=format_receipt(roll, context),
                                                kind="dice_result", visibility=visibility)))
    if hidden and not (origin and origin.private):
        key = hashlib.sha256(json.dumps(sorted(hidden), separators=(",", ":")).encode()).hexdigest()
        outputs.append(("hidden:" + key, Output(text=HIDDEN_NOTICE, kind="hidden_dice_notice")))
    return outputs


def queue_receipt_delivery(db, campaign_id, actor, request_id, event_id, state,
                           receipt_outputs, business_outputs, hidden_keys):
    """Only parent rows are deliverable; stable child rows are local indexes.

    An index has no network receipt or delivery success. Its parent and the
    parent's normal delivery parts are the only delivery evidence. Existing
    per-roll rows, of any status, are immutable and never rebound here.
    """
    from cockp.runtime.official_transport import bind_outbox
    def dump(value):
        return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    def ident(key, destination):
        return str(uuid.uuid5(uuid.NAMESPACE_URL, dump(["dice-receipt", campaign_id, key, destination])))
    def destinations(output):
        vis = output.get("visibility", {"scope": "public"})
        if vis["scope"] == "public":
            return ["group:" + actor.group_id]
        users = vis.get("recipients", []) if vis["scope"] == "private" else state["manager_ids"]
        return ["user:" + user for user in dict.fromkeys(users)]
    new, notices, hidden = [], [], set()
    for key, output in receipt_outputs:
        if output["kind"] == "hidden_dice_notice":
            notices.append(output)
            continue
        for destination in destinations(output):
            index_id = ident(key, destination)
            if db.execute("SELECT 1 FROM outbox WHERE id=?", (index_id,)).fetchone():
                continue
            new.append((index_id, destination, output["text"]))
            if key in hidden_keys:
                hidden.add(key)
    # Only new hidden results justify a new group notice. In particular,
    # regrouping previously used rolls must not create another public notice.
    if hidden:
        notice_key = "hidden:" + hashlib.sha256(dump(sorted(hidden)).encode()).hexdigest()
        for output in notices:
            for destination in destinations(output):
                index_id = ident(notice_key, destination)
                if not db.execute("SELECT 1 FROM outbox WHERE id=?", (index_id,)).fetchone():
                    new.append((index_id, destination, output["text"]))
    groups = {}
    for index_id, destination, text in new:
        groups.setdefault(destination, {"indexes": [], "texts": []})
        groups[destination]["indexes"].append((index_id, text))
        groups[destination]["texts"].append(text)
    unbatched = []
    for output in business_outputs:
        for destination in destinations(output):
            if destination in groups:
                groups[destination]["texts"].append(output["text"])
            else:
                unbatched.append((destination, output["text"]))
    now = time.time()
    for destination, group in groups.items():
        parent = str(uuid.uuid5(uuid.NAMESPACE_URL, dump(["dice-delivery", campaign_id, request_id, destination])))
        # requests and the parent commit together. A pre-existing parent without
        # its request is inconsistent state, never permission to resend it.
        if db.execute("SELECT 1 FROM outbox WHERE id=?", (parent,)).fetchone():
            raise ValueError("dice_delivery_parent_already_exists")
        db.execute("INSERT INTO outbox(id,campaign_id,event_id,destination,content,created_at) VALUES(?,?,?,?,?,?)",
                   (parent, campaign_id, event_id, destination, "\n\n".join(group["texts"]), now))
        bind_outbox(db, parent)
        pointer = dump({"kind": "dice_receipt_index", "parent_outbox_id": parent})
        for index_id, text in group["indexes"]:
            db.execute("INSERT INTO outbox(id,campaign_id,event_id,destination,content,status,attempts,receipt,created_at) "
                       "VALUES(?,?,?,?,?,'receipt_index',0,?,?)",
                       (index_id, campaign_id, event_id, destination, text, pointer, now))
    for destination, text in unbatched:
        outbox_id = str(uuid.uuid4())
        db.execute("INSERT INTO outbox(id,campaign_id,event_id,destination,content,created_at) VALUES(?,?,?,?,?,?)",
                   (outbox_id, campaign_id, event_id, destination, text, now))
        bind_outbox(db, outbox_id)
